  3	public final class Trie {
  4	    private static final int ALPHABET_SIZE = 26;
  5	    private static final char FIRST_LETTER = 'a';
  6	    private static final char LAST_LETTER = 'z';
  7	
  8	    private final TrieNode root = new TrieNode();
  9	
 10	    /**
 11	     * Adds a lowercase word to the trie.
 12	     */
 13	    public void insert(String word) {
 14	        Objects.requireNonNull(word, "word must not be null");
 15	        TrieNode current = root;
 16	
 17	        for (int position = 0; position < word.length(); position++) {
 18	            int index = toIndex(word.charAt(position), word);
 19	            current = current.getOrCreateChild(index);
 20	        }
 21	
 22	        current.markWord();
 23	    }
 24	
 25	    /**
 26	     * Returns true when the trie contains the complete lowercase word.
 27	     */
 28	    public boolean contains(String word) {
 29	        TrieNode node = findNode(word);
 30	        return node != null && node.isWord();
 31	    }
