 54	    private TrieNode findNode(String value) {
 55	        Objects.requireNonNull(value, "value must not be null");
 56	        TrieNode current = root;
 57	
 58	        for (int position = 0; position < value.length(); position++) {
 59	            current = current.getChild(toIndex(value.charAt(position), value));
 60	            if (current == null) {
 61	                return null;
 62	            }
 63	        }
 64	
 65	        return current;
 66	    }
