 68	    private static int toIndex(char letter, String value) {
 69	        if (letter < FIRST_LETTER || letter > LAST_LETTER) {
 70	            throw new IllegalArgumentException(
 71	                "Trie values may only contain lowercase letters a-z: " + value);
 72	        }
 73	
 74	        return letter - FIRST_LETTER;
 75	    }
